SELECT Color, COUNT(*) AS ProductCount
FROM Production.Product
GROUP BY Color;

SELECT SalesOrderID, TotalDue,
       SUM(TotalDue) OVER () AS GrandTotal
FROM Sales.SalesOrderHeader;

SELECT ProductID, ListPrice,
       NTILE(4) OVER (ORDER BY ListPrice DESC) AS Quartile
FROM Production.Product;

SELECT * FROM (
  SELECT Year, Quarter, Amount FROM dbo.Sales
) AS src
PIVOT (SUM(Amount) FOR Quarter IN ([Q1],[Q2],[Q3],[Q4])) AS p;
